export abstract class LayerObject {          // the declared type of the layer
  protected constructor(public readonly id: number) {}
  protected version = 0;
  touch(): void { this.version++; }          // shared implementation
  abstract describe(): string;               // every member must provide it
}
export class User extends LayerObject {
  constructor(id: number, readonly email: string) { super(id); }
  describe(): string { return `user ${this.id}`; }
}
